# jax.numpy array functions m to z, place, put, windows, vectorize and index tricks.
# Expected values come from jax 0.12.0.1 (generated by a script; floats as hex literals).

a2t_expect_list <- function(object, expected, dtype = NULL) {
  testthat::expect_length(object, length(expected))
  for (i in seq_along(expected)) expect_jax_equal(object[[i]], expected[[i]], dtype = dtype)
}
a2t_x24 <- function(dtype = NULL) jnp_reshape(as_jax(seq(0, 23) * 0.5 - 3, dtype), c(2L, 3L, 4L))
a2t_m34 <- function(dtype = NULL) as_jax(matrix(c(1.25, -2, 0.5, 3, 4, 0.75, -1.5, 2, -0.25, 5, 1, -3.5), 3, byrow = TRUE), dtype)
a2t_stack_loop <- function(f, x, axis = 0L) {
  n <- dim(x)[axis + 1L]
  jnp_stack(lapply(seq_len(n) - 1L, function(i) f(lax_index_in_dim(x, i, axis, keepdims = FALSE))))
}

test_that("nonzero, where size and fill_value, and triangle indices match JAX", {
  skip_if_no_backend()
  a <- as_jax(matrix(c(0, 1.5, -2, 0, 3, 0), 2, byrow = TRUE))
  a2t_expect_list(jnp_nonzero(a), list(c(0L, 0L, 1L), c(1L, 2L, 1L)), dtype = "int32")
  a2t_expect_list(jnp_nonzero(a, size = 4, fill_value = -1), list(c(0L, 0L, 1L, -1L), c(1L, 2L, 1L, -1L)), dtype = "int32")
  a2t_expect_list(jnp_nonzero(a, size = 2), list(c(0L, 0L), c(1L, 2L)), dtype = "int32")
  a2t_expect_list(jnp_nonzero(a, size = 4, fill_value = list(-1, -2)), list(c(0L, 0L, 1L, -1L), c(1L, 2L, 1L, -2L)), dtype = "int32")
  a2t_expect_list(jnp_nonzero(a, size = 3, fill_value = 0.5), list(c(0, 0, 1), c(1, 2, 1)), dtype = "float32")
  a2t_expect_list(jnp_nonzero(c(TRUE, FALSE, TRUE)), list(c(0L, 2L)), dtype = "int32")
  a2t_expect_list(jnp_nonzero(jnp_zeros(c(0L, 3L)), size = 2), list(c(0L, 0L), c(0L, 0L)), dtype = "int32")
  a2t_expect_list(jit(function(x) jnp_nonzero(x, size = 3, fill_value = 7L))(a), list(c(0L, 0L, 1L), c(1L, 2L, 1L)), dtype = "int32")
  expect_error(jit(function(x) jnp_nonzero(x))(a), class = "jax_concretization_error")
  expect_error(jnp_nonzero(as_jax(1)), "Calling nonzero on 0d arrays is not allowed")
  expect_error(jnp_nonzero(a, size = 2, fill_value = list(1, 2, 3)), "fill_value tuple must have length equal to number of axes")
  expect_error(jnp_nonzero(a, size = -1), "size must be a positive integer")
  a2t_expect_list(jnp_mask_indices(3, jnp_triu, 1), list(c(0L, 0L, 1L), c(1L, 2L, 2L)), dtype = "int32")
  a2t_expect_list(jnp_mask_indices(3, jnp_tril, size = 8), list(c(0L, 1L, 1L, 2L, 2L, 2L, 0L, 0L), c(0L, 0L, 1L, 0L, 1L, 2L, 0L, 0L)), dtype = "int32")
  a2t_expect_list(jnp_triu_indices(3), list(c(0L, 0L, 0L, 1L, 1L, 2L), c(0L, 1L, 2L, 1L, 2L, 2L)), dtype = "int32")
  a2t_expect_list(jnp_triu_indices(3, k = 1, m = 4), list(c(0L, 0L, 0L, 1L, 1L, 2L), c(1L, 2L, 3L, 2L, 3L, 3L)), dtype = "int32")
  a2t_expect_list(jnp_triu_indices(4, k = -2, m = 3), list(c(0L, 0L, 0L, 1L, 1L, 1L, 2L, 2L, 2L, 3L, 3L), c(0L, 1L, 2L, 0L, 1L, 2L, 0L, 1L, 2L, 1L, 2L)), dtype = "int32")
  a2t_expect_list(jnp_tril_indices(3, k = -1), list(c(1L, 2L, 2L), c(0L, 0L, 1L)), dtype = "int32")
  a2t_expect_list(jnp_tril_indices(2, k = 1, m = 4), list(c(0L, 0L, 1L, 1L, 1L), c(0L, 1L, 0L, 1L, 2L)), dtype = "int32")
  a2t_expect_list(jnp_tril_indices_from(matrix(0, 3, 4)), list(c(0L, 1L, 1L, 2L, 2L, 2L), c(0L, 0L, 1L, 0L, 1L, 2L)), dtype = "int32")
  a2t_expect_list(jnp_triu_indices_from(matrix(0, 4, 2), k = -1), list(c(0L, 0L, 1L, 1L, 2L), c(0L, 1L, 0L, 1L, 1L)), dtype = "int32")
  expect_error(jnp_triu_indices_from(c(1, 2)), "Only 2-D inputs are accepted")
})

test_that("nonzero batches, works in x64 and has zero gradients", {
  skip_if_no_backend()
  a <- as_jax(matrix(c(0, 1.5, -2, 0, 3, 0), 2, byrow = TRUE))
  f <- function(x) jnp_nonzero(x, size = 2, fill_value = -1)[[1L]]
  expect_jax_equal(vmap(f)(a), a2t_stack_loop(f, a))
  expect_jax_equal(vmap(f, in_axes = 1L)(a), a2t_stack_loop(f, a, 1L))
  enable_x64()
  on.exit(enable_x64(FALSE))
  a2t_expect_list(jnp_nonzero(as_jax(matrix(c(0, 1.5, -2, 0, 3, 0), 2, byrow = TRUE), "float64"), size = 4), list(c(0L, 0L, 1L, 0L), c(1L, 2L, 1L, 0L)), dtype = "int64")
  expect_jax_equal(grad(function(x) jnp_sum(x * jnp_nonzero(x, size = 3)[[1L]]))(as_jax(matrix(c(0, 1.5, -2, 0, 3, 0), 2, byrow = TRUE), "float64")), array(c(0, 0, 0, 0, 1, 1), c(2, 3)), dtype = "float64")
})

test_that("place, put, unravel_index and ravel_multi_index match JAX", {
  skip_if_no_backend()
  p <- as_jax(matrix(1:6, 2, byrow = TRUE), "float32")
  mask <- matrix(c(TRUE, FALSE, TRUE, FALSE, TRUE, TRUE), 2, byrow = TRUE)
  expect_jax_equal(jnp_place(p, mask, c(10, 20), inplace = FALSE), array(c(10, 4, 2, 10, 20, 20), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_place(p, mask, c(10, 20, 30, 40, 50), inplace = FALSE), array(c(10, 4, 2, 30, 20, 40), c(2, 3)), dtype = "float32")
  expect_jax_equal(jit(function(x, m) jnp_place(x, m, c(-1, -2), inplace = FALSE))(p, mask), array(c(-1, 4, 2, -1, -2, -2), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_put(p, c(0, 5), c(10, 20), inplace = FALSE), array(c(10, 4, 2, 5, 3, 20), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_put(p, c(1, 7, -9), 9, inplace = FALSE), array(c(9, 4, 9, 5, 3, 9), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_put(p, c(1, 7, -9), c(7, 8, 9), mode = "clip", inplace = FALSE), array(c(9, 4, 7, 5, 3, 8), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_put(p, c(1, 7, -9), c(7, 8, 9), mode = "wrap", inplace = FALSE), array(c(1, 9, 8, 5, 3, 6), c(2, 3)), dtype = "float32")
  expect_jax_equal(jit(function(x, i) jnp_put(x, i, c(5, 6), inplace = FALSE))(p, c(2L, 3L)), array(c(1, 6, 2, 5, 5, 6), c(2, 3)), dtype = "float32")
  expect_error(jnp_place(p, mask, 1), "cannot modify arrays in-place")
  expect_error(jnp_place(p, c(TRUE, FALSE), 1, inplace = FALSE), "arr and mask must be the same size")
  expect_error(jnp_place(p, mask, numeric(0), inplace = FALSE), "Cannot place values from an empty array")
  expect_error(jnp_put(p, 0, 1), "cannot modify arrays in-place")
  expect_error(jnp_put(p, 0, 1, mode = "raise", inplace = FALSE), class = "jax_not_implemented_error")
  expect_error(jnp_put(p, 0, 1, mode = "bad", inplace = FALSE), "mode should be one of")
  a2t_expect_list(jnp_unravel_index(c(5, 7, 22, -1, -3, 0), c(3, 4)), list(c(1L, 1L, 2L, 2L, 2L, 0L), c(1L, 3L, 3L, 3L, 1L, 0L)), dtype = "int32")
  a2t_expect_list(jnp_unravel_index(as_jax(c(5, 11), "uint8"), c(2L, 2L, 3L)), list(c(0L, 1L), c(1L, 1L), c(2L, 2L)), dtype = "uint8")
  a2t_expect_list(jnp_unravel_index(4L, 6L), list(4L), dtype = "int32")
  expect_jax_equal(jnp_ravel_multi_index(list(c(1, 2, 0), c(3, 0, 2)), c(3, 4)), c(7L, 8L, 2L), dtype = "int32")
  expect_jax_equal(jnp_ravel_multi_index(list(c(1, 5), c(-1, 2)), c(3, 4), mode = "clip"), c(4L, 10L), dtype = "int32")
  expect_jax_equal(jnp_ravel_multi_index(list(c(1, 5), c(-1, 2)), c(3, 4), mode = "wrap", order = "F"), c(10L, 8L), dtype = "int32")
  expect_jax_equal(jnp_ravel_multi_index(list(2L, 1L), c(3, 4), dtype = "int16"), 9L, dtype = "int16")
  expect_jax_equal(jit(function(i, j) jnp_ravel_multi_index(list(i, j), c(3, 4), mode = "wrap"))(c(1L, 4L), c(5L, 0L)), c(5L, 4L), dtype = "int32")
  expect_error(jnp_ravel_multi_index(list(c(1, 5), c(0, 0)), c(3, 4)), "invalid entry in coordinates array")
  expect_error(jit(function(i) jnp_ravel_multi_index(list(i, i), c(3, 4)))(c(1L, 2L)), class = "jax_concretization_error")
  expect_error(jnp_ravel_multi_index(list(1, 2), c(3, 4), mode = "bad"), "invalid mode")
  expect_error(jnp_ravel_multi_index(list(c(0.5, 1.5), 1L), c(3, 4), mode = "clip"), "dtype=float32 is not an integer type")
  expect_error(jnp_ravel_multi_index(list(c(0.5, 1.5), 1L), c(3, 4), mode = "clip", dtype = "int32"), "only int indices permitted")
  expect_error(jnp_ravel_multi_index(list(1L, 2L), c(300, 400), dtype = "int8"), "not large enough to hold flattened index")
  enable_x64()
  on.exit(enable_x64(FALSE))
  b <- as_jax(c(1, 2, 3), "float64")
  check_grad_fd(function(v) jnp_sum(jnp_sin(jnp_put(jnp_arange(6) * 0.5, c(4, 1, 2), v, inplace = FALSE))), b)
  check_grad_fd(function(v) jnp_sum(jnp_place(jnp_arange(6) * 0.5, c(TRUE, FALSE, TRUE, FALSE, TRUE, FALSE), v, inplace = FALSE)^2), b)
  a2t_expect_list(jnp_unravel_index(c(5, 7), c(3L, 4L)), list(c(1L, 1L), c(1L, 3L)), dtype = "int64")
})

test_that("permute_dims, matrix_transpose, rot90 and rollaxis match JAX", {
  skip_if_no_backend()
  x <- a2t_x24()
  expect_jax_equal(jnp_permute_dims(x, c(2, 0, 1)), array(c(-3, -0x1.4000000000000p+1, -2, -0x1.8000000000000p+0, 3, 0x1.c000000000000p+1, 4, 0x1.2000000000000p+2, -1, -0x1.0000000000000p-1, 0, 0x1.0000000000000p-1, 5, 0x1.6000000000000p+2, 6, 0x1.a000000000000p+2, 1, 0x1.8000000000000p+0, 2, 0x1.4000000000000p+1, 7, 0x1.e000000000000p+2, 8, 0x1.1000000000000p+3), c(4, 2, 3)), dtype = "float32")
  expect_jax_equal(jnp_matrix_transpose(x), array(c(-3, 3, -0x1.4000000000000p+1, 0x1.c000000000000p+1, -2, 4, -0x1.8000000000000p+0, 0x1.2000000000000p+2, -1, 5, -0x1.0000000000000p-1, 0x1.6000000000000p+2, 0, 6, 0x1.0000000000000p-1, 0x1.a000000000000p+2, 1, 7, 0x1.8000000000000p+0, 0x1.e000000000000p+2, 2, 8, 0x1.4000000000000p+1, 0x1.1000000000000p+3), c(2, 4, 3)), dtype = "float32")
  expect_jax_equal(jnp_rot90(x, k = 1L, axes = c(1, 2)), array(c(-0x1.8000000000000p+0, 0x1.2000000000000p+2, -2, 4, -0x1.4000000000000p+1, 0x1.c000000000000p+1, -3, 3, 0x1.0000000000000p-1, 0x1.a000000000000p+2, 0, 6, -0x1.0000000000000p-1, 0x1.6000000000000p+2, -1, 5, 0x1.4000000000000p+1, 0x1.1000000000000p+3, 2, 8, 0x1.8000000000000p+0, 0x1.e000000000000p+2, 1, 7), c(2, 4, 3)), dtype = "float32")
  expect_jax_equal(jnp_rot90(x, k = 2L, axes = c(1, 2)), array(c(0x1.4000000000000p+1, 0x1.1000000000000p+3, 0x1.0000000000000p-1, 0x1.a000000000000p+2, -0x1.8000000000000p+0, 0x1.2000000000000p+2, 2, 8, 0, 6, -2, 4, 0x1.8000000000000p+0, 0x1.e000000000000p+2, -0x1.0000000000000p-1, 0x1.6000000000000p+2, -0x1.4000000000000p+1, 0x1.c000000000000p+1, 1, 7, -1, 5, -3, 3), c(2, 3, 4)), dtype = "float32")
  expect_jax_equal(jnp_rot90(x, k = 3L, axes = c(1, 2)), array(c(1, 7, 0x1.8000000000000p+0, 0x1.e000000000000p+2, 2, 8, 0x1.4000000000000p+1, 0x1.1000000000000p+3, -1, 5, -0x1.0000000000000p-1, 0x1.6000000000000p+2, 0, 6, 0x1.0000000000000p-1, 0x1.a000000000000p+2, -3, 3, -0x1.4000000000000p+1, 0x1.c000000000000p+1, -2, 4, -0x1.8000000000000p+0, 0x1.2000000000000p+2), c(2, 4, 3)), dtype = "float32")
  expect_jax_equal(jnp_rot90(x, k = -1L, axes = c(1, 2)), array(c(1, 7, 0x1.8000000000000p+0, 0x1.e000000000000p+2, 2, 8, 0x1.4000000000000p+1, 0x1.1000000000000p+3, -1, 5, -0x1.0000000000000p-1, 0x1.6000000000000p+2, 0, 6, 0x1.0000000000000p-1, 0x1.a000000000000p+2, -3, 3, -0x1.4000000000000p+1, 0x1.c000000000000p+1, -2, 4, -0x1.8000000000000p+0, 0x1.2000000000000p+2), c(2, 4, 3)), dtype = "float32")
  expect_jax_equal(jnp_rot90(x, k = 0L, axes = c(1, 2)), array(c(-3, 3, -1, 5, 1, 7, -0x1.4000000000000p+1, 0x1.c000000000000p+1, -0x1.0000000000000p-1, 0x1.6000000000000p+2, 0x1.8000000000000p+0, 0x1.e000000000000p+2, -2, 4, 0, 6, 2, 8, -0x1.8000000000000p+0, 0x1.2000000000000p+2, 0x1.0000000000000p-1, 0x1.a000000000000p+2, 0x1.4000000000000p+1, 0x1.1000000000000p+3), c(2, 3, 4)), dtype = "float32")
  expect_jax_equal(jnp_rot90(x, axes = c(2, 0)), array(c(3, 0x1.c000000000000p+1, 4, 0x1.2000000000000p+2, 5, 0x1.6000000000000p+2, 6, 0x1.a000000000000p+2, 7, 0x1.e000000000000p+2, 8, 0x1.1000000000000p+3, -3, -0x1.4000000000000p+1, -2, -0x1.8000000000000p+0, -1, -0x1.0000000000000p-1, 0, 0x1.0000000000000p-1, 1, 0x1.8000000000000p+0, 2, 0x1.4000000000000p+1), c(4, 3, 2)), dtype = "float32")
  expect_jax_equal(jnp_rollaxis(x, 2), array(c(-3, -0x1.4000000000000p+1, -2, -0x1.8000000000000p+0, 3, 0x1.c000000000000p+1, 4, 0x1.2000000000000p+2, -1, -0x1.0000000000000p-1, 0, 0x1.0000000000000p-1, 5, 0x1.6000000000000p+2, 6, 0x1.a000000000000p+2, 1, 0x1.8000000000000p+0, 2, 0x1.4000000000000p+1, 7, 0x1.e000000000000p+2, 8, 0x1.1000000000000p+3), c(4, 2, 3)), dtype = "float32")
  expect_jax_equal(jnp_rollaxis(x, 0, 3), array(c(-3, -1, 1, -0x1.4000000000000p+1, -0x1.0000000000000p-1, 0x1.8000000000000p+0, -2, 0, 2, -0x1.8000000000000p+0, 0x1.0000000000000p-1, 0x1.4000000000000p+1, 3, 5, 7, 0x1.c000000000000p+1, 0x1.6000000000000p+2, 0x1.e000000000000p+2, 4, 6, 8, 0x1.2000000000000p+2, 0x1.a000000000000p+2, 0x1.1000000000000p+3), c(3, 4, 2)), dtype = "float32")
  expect_jax_equal(jnp_rollaxis(x, -1, 1), array(c(-3, 3, -0x1.4000000000000p+1, 0x1.c000000000000p+1, -2, 4, -0x1.8000000000000p+0, 0x1.2000000000000p+2, -1, 5, -0x1.0000000000000p-1, 0x1.6000000000000p+2, 0, 6, 0x1.0000000000000p-1, 0x1.a000000000000p+2, 1, 7, 0x1.8000000000000p+0, 0x1.e000000000000p+2, 2, 8, 0x1.4000000000000p+1, 0x1.1000000000000p+3), c(2, 4, 3)), dtype = "float32")
  expect_error(jnp_permute_dims(x, c(0, 0, 1)), "must be a permutation")
  expect_error(jnp_matrix_transpose(c(1, 2)), "must be at least two-dimensional")
  expect_error(jnp_rot90(c(1, 2)), "rot90 requires its first argument to have ndim at least two")
  expect_error(jnp_rot90(x, axes = c(1, 1)), "Axes must be different")
  expect_error(jnp_rollaxis(x, 0, 5), "must satisfy")
})

test_that("resize, tile, repeat and roll match JAX", {
  skip_if_no_backend()
  m <- a2t_m34()
  expect_jax_equal(jnp_resize(jnp_arange(5), c(2, 4)), array(c(0L, 4L, 1L, 0L, 2L, 1L, 3L, 2L), c(2, 4)), dtype = "int32")
  expect_jax_equal(jnp_resize(m, 5), c(0x1.4000000000000p+0, -2, 0x1.0000000000000p-1, 3, 4), dtype = "float32")
  expect_jax_equal(jnp_resize(m, c(0, 2)), array(numeric(0), c(0, 2)), dtype = "float32")
  expect_jax_equal(jnp_tile(c(1L, 2L), c(2, 1, 2)), array(c(1L, 1L, 2L, 2L, 1L, 1L, 2L, 2L), c(2, 1, 4)), dtype = "int32")
  expect_jax_equal(jnp_tile(m, 2), array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1), c(3, 8)), dtype = "float32")
  expect_jax_equal(jnp_tile(m, c(2, 1)), array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -2, 0x1.8000000000000p-1, 5, -2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1, 3, 2, -0x1.c000000000000p+1), c(6, 4)), dtype = "float32")
  expect_jax_equal(jnp_tile(m, c(1, 0)), array(numeric(0), c(3, 0)), dtype = "float32")
  expect_jax_equal(jnp_tile(as_jax(3L), 3), c(3L, 3L, 3L), dtype = "int32")
  expect_jax_equal(jnp_repeat(m, 2), c(0x1.4000000000000p+0, 0x1.4000000000000p+0, -2, -2, 0x1.0000000000000p-1, 0x1.0000000000000p-1, 3, 3, 4, 4, 0x1.8000000000000p-1, 0x1.8000000000000p-1, -0x1.8000000000000p+0, -0x1.8000000000000p+0, 2, 2, -0x1.0000000000000p-2, -0x1.0000000000000p-2, 5, 5, 1, 1, -0x1.c000000000000p+1, -0x1.c000000000000p+1), dtype = "float32")
  expect_jax_equal(jnp_repeat(m, 2, axis = 0), array(c(0x1.4000000000000p+0, 0x1.4000000000000p+0, 4, 4, -0x1.0000000000000p-2, -0x1.0000000000000p-2, -2, -2, 0x1.8000000000000p-1, 0x1.8000000000000p-1, 5, 5, 0x1.0000000000000p-1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, -0x1.8000000000000p+0, 1, 1, 3, 3, 2, 2, -0x1.c000000000000p+1, -0x1.c000000000000p+1), c(6, 4)), dtype = "float32")
  expect_jax_equal(jnp_repeat(m, c(1, 0, 3, 2), axis = 1), array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1, 3, 2, -0x1.c000000000000p+1), c(3, 6)), dtype = "float32")
  expect_jax_equal(jnp_repeat(m, c(2, 0, 1), axis = -2), array(c(0x1.4000000000000p+0, 0x1.4000000000000p+0, -0x1.0000000000000p-2, -2, -2, 5, 0x1.0000000000000p-1, 0x1.0000000000000p-1, 1, 3, 3, -0x1.c000000000000p+1), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_repeat(as_jax(2.5), 3), c(0x1.4000000000000p+1, 0x1.4000000000000p+1, 0x1.4000000000000p+1), dtype = "float32")
  expect_jax_equal(jnp_repeat(m, 0, axis = 1), array(numeric(0), c(3, 0)), dtype = "float32")
  expect_jax_equal(jnp_repeat(m, c(1, 0, 3, 2), axis = 1, total_repeat_length = 4), array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1), c(3, 4)), dtype = "float32")
  expect_jax_equal(jit(function(x, r) jnp_repeat(x, r, axis = 0, total_repeat_length = 7))(m, c(2L, 1L, 3L)), array(c(0x1.4000000000000p+0, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -0x1.0000000000000p-2, -0x1.0000000000000p-2, -0x1.0000000000000p-2, -2, -2, 0x1.8000000000000p-1, 5, 5, 5, 5, 0x1.0000000000000p-1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 1, 1, 1, 3, 3, 2, -0x1.c000000000000p+1, -0x1.c000000000000p+1, -0x1.c000000000000p+1, -0x1.c000000000000p+1), c(7, 4)), dtype = "float32")
  expect_jax_equal(jit(function(x, r) jnp_repeat(x, r, total_repeat_length = 5))(c(1, 2, 3), 2L), c(1, 1, 2, 2, 3), dtype = "float32")
  expect_error(jit(function(x, r) jnp_repeat(x, r))(m, 2L), class = "jax_concretization_error")
  expect_error(jnp_repeat(as_jax(1), c(1, 2), axis = 0), "only implemented for scalar values")
  expect_error(jnp_repeat(as_jax(1), c(1, 2)), "operands could not be broadcast together")
  expect_jax_equal(jnp_roll(m, 1), array(c(-0x1.c000000000000p+1, 3, 2, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_roll(m, -1, axis = 1), array(c(-2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_roll(m, c(1, 5), axis = c(0, 1)), array(c(-0x1.c000000000000p+1, 3, 2, -0x1.0000000000000p-2, 0x1.4000000000000p+0, 4, 5, -2, 0x1.8000000000000p-1, 1, 0x1.0000000000000p-1, -0x1.8000000000000p+0), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_roll(m, 2, axis = c(0, 1, 0)), array(c(1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, -0x1.c000000000000p+1, 3, 2, -0x1.0000000000000p-2, 0x1.4000000000000p+0, 4, 5, -2, 0x1.8000000000000p-1), c(3, 4)), dtype = "float32")
  expect_jax_equal(jit(function(x, s) jnp_roll(x, s, axis = 1))(m, 3L), array(c(-2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2), c(3, 4)), dtype = "float32")
  expect_jax_equal(jit(function(x, s) jnp_roll(x, s, axis = c(1, 0)))(m, c(-2L, 7L)), array(c(1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, -0x1.c000000000000p+1, 3, 2, -0x1.0000000000000p-2, 0x1.4000000000000p+0, 4, 5, -2, 0x1.8000000000000p-1), c(3, 4)), dtype = "float32")
  expect_jax_equal(jit(function(x, s) jnp_roll(x, s))(m, 5L), array(c(2, -0x1.c000000000000p+1, 3, -0x1.0000000000000p-2, 0x1.4000000000000p+0, 4, 5, -2, 0x1.8000000000000p-1, 1, 0x1.0000000000000p-1, -0x1.8000000000000p+0), c(3, 4)), dtype = "float32")
  expect_error(jit(function(x, s) jnp_roll(x, s, axis = 0))(m, matrix(1L, 2, 2)), "must be scalars or 1D arrays")
})

test_that("split, vsplit, unstack, vstack and meshgrid match JAX", {
  skip_if_no_backend()
  m <- a2t_m34()
  a2t_expect_list(jnp_split(jnp_arange(6), 3), list(c(0L, 1L), c(2L, 3L), c(4L, 5L)), dtype = "int32")
  a2t_expect_list(jnp_split(jnp_arange(6), list(2, 5)), list(c(0L, 1L), c(2L, 3L, 4L), c(5L)), dtype = "int32")
  a2t_expect_list(jnp_split(jnp_arange(6), c(-4, 9)), list(c(0L, 1L), c(2L, 3L, 4L, 5L), integer(0)), dtype = "int32")
  a2t_expect_list(jnp_split(m, 2, axis = 1), list(array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -2, 0x1.8000000000000p-1, 5), c(3, 2)), array(c(0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1), c(3, 2))), dtype = "float32")
  a2t_expect_list(jnp_split(m, list(1), axis = -1), list(array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2), c(3, 1)), array(c(-2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1), c(3, 3))), dtype = "float32")
  a2t_expect_list(jnp_split(m, as_jax(c(1L, 2L))), list(array(c(0x1.4000000000000p+0, -2, 0x1.0000000000000p-1, 3), c(1, 4)), array(c(4, 0x1.8000000000000p-1, -0x1.8000000000000p+0, 2), c(1, 4)), array(c(-0x1.0000000000000p-2, 5, 1, -0x1.c000000000000p+1), c(1, 4))), dtype = "float32")
  a2t_expect_list(jnp_vsplit(m, 3), list(array(c(0x1.4000000000000p+0, -2, 0x1.0000000000000p-1, 3), c(1, 4)), array(c(4, 0x1.8000000000000p-1, -0x1.8000000000000p+0, 2), c(1, 4)), array(c(-0x1.0000000000000p-2, 5, 1, -0x1.c000000000000p+1), c(1, 4))), dtype = "float32")
  a2t_expect_list(jnp_unstack(m), list(c(0x1.4000000000000p+0, -2, 0x1.0000000000000p-1, 3), c(4, 0x1.8000000000000p-1, -0x1.8000000000000p+0, 2), c(-0x1.0000000000000p-2, 5, 1, -0x1.c000000000000p+1)), dtype = "float32")
  a2t_expect_list(jnp_unstack(m, axis = 1), list(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2), c(-2, 0x1.8000000000000p-1, 5), c(0x1.0000000000000p-1, -0x1.8000000000000p+0, 1), c(3, 2, -0x1.c000000000000p+1)), dtype = "float32")
  expect_error(jnp_split(m, 2), "array split does not result in an equal division: rest is 1")
  expect_error(jit(function(x, i) jnp_split(x, i))(m, c(1L, 2L)), class = "jax_concretization_error")
  expect_jax_equal(jnp_vstack(list(c(1, 2), c(3, 4))), array(c(1, 3, 2, 4), c(2, 2)), dtype = "float32")
  expect_jax_equal(jnp_vstack(list(1L, as_jax(2, "float32"))), array(c(1, 2), c(2, 1)), dtype = "float32")
  expect_jax_equal(jnp_vstack(list(m, c(1L, 2L, 3L, 4L))), array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, 1, -2, 0x1.8000000000000p-1, 5, 2, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 3, 2, -0x1.c000000000000p+1, 4), c(4, 4)), dtype = "float32")
  expect_jax_equal(jnp_vstack(m), array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_vstack(list(c(1L, 2L), c(3L, 4L)), dtype = "float32"), array(c(1, 3, 2, 4), c(2, 2)), dtype = "float32")
  a2t_expect_list(jnp_meshgrid(c(1, 2, 3), c(4, 5)), list(array(c(1, 1, 2, 2, 3, 3), c(2, 3)), array(c(4, 5, 4, 5, 4, 5), c(2, 3))), dtype = "float32")
  a2t_expect_list(jnp_meshgrid(c(1, 2, 3), c(4, 5), indexing = "ij"), list(array(c(1, 2, 3, 1, 2, 3), c(3, 2)), array(c(4, 4, 4, 5, 5, 5), c(3, 2))), dtype = "float32")
  a2t_expect_list(jnp_meshgrid(c(1L, 2L), c(4L, 5L, 6L), 7L:8L, sparse = TRUE), list(array(c(1L, 2L), c(1, 2, 1)), array(c(4L, 5L, 6L), c(3, 1, 1)), array(c(7L, 8L), c(1, 1, 2))), dtype = "int32")
  a2t_expect_list(jnp_meshgrid(c(1, 2)), list(c(1, 2)), dtype = "float32")
  expect_error(jnp_meshgrid(m), "must be 1D")
  expect_error(jnp_meshgrid(c(1, 2), indexing = "xx"), "Valid values for indexing")
  expect_error(jnp_meshgrid(c(1, 2), copy = FALSE), "only supports copy=True")
})

test_that("shape functions differentiate, batch and work in x64", {
  skip_if_no_backend()
  enable_x64()
  on.exit(enable_x64(FALSE))
  m <- a2t_m34("float64")
  w3 <- jnp_reshape(jnp_arange(1, 13), c(3L, 4L))
  check_grad_fd(function(x) jnp_sum(jnp_sin(jnp_repeat(x, c(2, 0, 1), axis = 0))), m)
  check_grad_fd(function(x) jnp_sum(jnp_cos(jnp_tile(x, c(2, 1))) * jnp_tile(w3, c(2, 1))), m)
  check_grad_fd(function(x) jnp_sum(jnp_roll(x, c(1, -1), axis = c(0, 1)) * w3), m)
  check_grad_fd(function(x) jnp_sum(jnp_rot90(x) * jnp_transpose(w3)), m)
  check_grad_fd(function(x) jnp_sum(jnp_resize(x, c(5, 3))^2), m)
  check_grad_fd(function(x) jnp_sum(jnp_split(x, list(1), axis = 1)[[2L]]^3), m)
  gs <- grad(function(x, s) jnp_sum(jnp_roll(x, s, axis = 1) * w3))(m, 1L)
  expect_jax_equal(gs, array(c(2, 6, 10, 3, 7, 11, 4, 8, 12, 1, 5, 9), c(3, 4)), dtype = "float64")
  expect_jax_equal(jnp_repeat(m, c(1, 2, 0), axis = 0), array(c(0x1.4000000000000p+0, 4, 4, -2, 0x1.8000000000000p-1, 0x1.8000000000000p-1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, -0x1.8000000000000p+0, 3, 2, 2), c(3, 4)), dtype = "float64")
  f <- function(x) jnp_tile(jnp_roll(x, 1L), 2)
  expect_jax_equal(vmap(f)(m), a2t_stack_loop(f, m))
  g <- function(x, s) jnp_roll(x, s)
  expect_jax_equal(vmap(g)(m, c(1L, -2L, 5L)), jnp_stack(list(g(m[0, ], 1L), g(m[1, ], -2L), g(m[2, ], 5L))))
  h <- function(x) jnp_repeat(x, c(1, 2, 0, 1))
  expect_jax_equal(vmap(h)(m), a2t_stack_loop(h, m))
  expect_jax_equal(vmap(function(x) jnp_split(x, 3)[[2L]], in_axes = 1L)(m), a2t_stack_loop(function(x) jnp_split(x, 3)[[2L]], m, 1L))
})

test_that("tri, tril, triu, trace and vander match JAX", {
  skip_if_no_backend()
  x <- a2t_x24()
  m <- a2t_m34()
  expect_jax_equal(jnp_tri(3), array(c(1, 1, 1, 0, 1, 1, 0, 0, 1), c(3, 3)), dtype = "float32")
  expect_jax_equal(jnp_tri(3, 4, k = 1, dtype = "int32"), array(c(1L, 1L, 1L, 1L, 1L, 1L, 0L, 1L, 1L, 0L, 0L, 1L), c(3, 4)), dtype = "int32")
  expect_jax_equal(jnp_tri(2, 5, k = -1, dtype = "bool"), array(c(FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE), c(2, 5)), dtype = "bool")
  expect_jax_equal(jnp_tril(m), array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, 0, 0x1.8000000000000p-1, 5, 0, 0, 1, 0, 0, 0), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_tril(x, k = 1), array(c(-3, 3, -1, 5, 1, 7, -0x1.4000000000000p+1, 0x1.c000000000000p+1, -0x1.0000000000000p-1, 0x1.6000000000000p+2, 0x1.8000000000000p+0, 0x1.e000000000000p+2, 0, 0, 0, 6, 2, 8, 0, 0, 0, 0, 0x1.4000000000000p+1, 0x1.1000000000000p+3), c(2, 3, 4)), dtype = "float32")
  expect_jax_equal(jnp_triu(x, k = -1), array(c(-3, 3, -1, 5, 0, 0, -0x1.4000000000000p+1, 0x1.c000000000000p+1, -0x1.0000000000000p-1, 0x1.6000000000000p+2, 0x1.8000000000000p+0, 0x1.e000000000000p+2, -2, 4, 0, 6, 2, 8, -0x1.8000000000000p+0, 0x1.2000000000000p+2, 0x1.0000000000000p-1, 0x1.a000000000000p+2, 0x1.4000000000000p+1, 0x1.1000000000000p+3), c(2, 3, 4)), dtype = "float32")
  expect_jax_equal(jnp_triu(matrix(1:6, 2), k = 1), array(c(0L, 0L, 3L, 0L, 5L, 6L), c(2, 3)), dtype = "int32")
  expect_jax_equal(jnp_trace(m), 3, dtype = "float32")
  expect_jax_equal(jnp_trace(m, offset = 1), -7, dtype = "float32")
  expect_jax_equal(jnp_trace(m, offset = -2), -0x1.0000000000000p-2, dtype = "float32")
  expect_jax_equal(jnp_trace(x, axis1 = 1, axis2 = 2), c(-0x1.8000000000000p+0, 0x1.0800000000000p+4), dtype = "float32")
  expect_jax_equal(jnp_trace(x, offset = 1, axis1 = 2, axis2 = 0), c(3, 5, 7), dtype = "float32")
  expect_jax_equal(jnp_trace(matrix(1:9, 3), dtype = "float32"), 15, dtype = "float32")
  expect_jax_equal(jnp_trace(as_jax(matrix(1:4, 2), "int8")), 5L, dtype = "int32")
  expect_jax_equal(jnp_vander(c(1, 2, 3, 5)), array(c(1, 8, 27, 125, 1, 4, 9, 25, 1, 2, 3, 5, 1, 1, 1, 1), c(4, 4)), dtype = "float32")
  expect_jax_equal(jnp_vander(c(1, 2, 3, 5), N = 3, increasing = TRUE), array(c(1, 1, 1, 1, 1, 2, 3, 5, 1, 4, 9, 25), c(4, 3)), dtype = "float32")
  expect_jax_equal(jnp_vander(c(2L, -3L), N = 4), array(c(8L, -27L, 4L, 9L, 2L, -3L, 1L, 1L), c(2, 4)), dtype = "int32")
  expect_jax_equal(jnp_vander(c(1.5, 2), N = 0), array(numeric(0), c(2, 0)), dtype = "float32")
  expect_error(jnp_tril(c(1, 2)), "Argument to jax.numpy.tril must be at least 2D")
  expect_error(jnp_triu(3), "Argument to jax.numpy.triu must be at least 2D")
  expect_error(jnp_trace(m, axis1 = 1, axis2 = -1), "axis1 and axis2 can not be same")
  expect_error(jnp_trace(m, out = 1), class = "jax_not_implemented_error")
  expect_error(jnp_vander(m), "x must be a one-dimensional array")
  expect_error(jnp_vander(c(1, 2), N = -1), "N must be nonnegative")
  expect_error(jnp_tri(2, k = 0.5), "offset must be an integer")
  expect_jax_equal(jit(function(x) jnp_trace(jnp_tril(x, k = 1)))(m), 3, dtype = "float32")
  enable_x64()
  on.exit(enable_x64(FALSE))
  m <- a2t_m34("float64")
  check_grad_fd(function(x) jnp_sum(jnp_sin(jnp_tril(x, k = 1)) + jnp_triu(x)^2), m)
  check_grad_fd(function(x) jnp_trace(x, offset = 1) * jnp_trace(x), m)
  check_grad_fd(function(v) jnp_sum(jnp_vander(v, N = 4)), as_jax(c(0.5, -1.25, 2), "float64"))
  expect_jax_equal(jnp_vander(as_jax(c(0.5, -1.25, 2), "float64"), N = 4), array(c(0x1.0000000000000p-3, -0x1.f400000000000p+0, 8, 0x1.0000000000000p-2, 0x1.9000000000000p+0, 4, 0x1.0000000000000p-1, -0x1.4000000000000p+0, 2, 1, 1, 1), c(3, 4)), dtype = "float64")
  expect_jax_equal(jnp_tri(2, 3), array(c(1, 1, 0, 1, 0, 0), c(2, 3)), dtype = "float64")
  expect_jax_equal(vmap(function(x) jnp_triu(x, k = 1))(a2t_x24("float64")), a2t_stack_loop(function(x) jnp_triu(x, k = 1), a2t_x24("float64")))
  expect_jax_equal(vmap(jnp_trace, in_axes = 2L)(a2t_x24("float64")), a2t_stack_loop(jnp_trace, a2t_x24("float64"), 2L))
})

test_that("select, piecewise, nan_to_num and unwrap match JAX", {
  skip_if_no_backend()
  xs <- c(-2, -0.5, 0, 0.5, 1.5, 3)
  expect_jax_equal(jnp_select(list(xs < 0, xs > 1), list(xs^2, xs * 10)), c(4, 0x1.0000000000000p-2, 0, 0, 15, 30), dtype = "float32")
  expect_jax_equal(jnp_select(list(xs < 1, xs > -1), list(1L:6L, -(1L:6L)), default = 99L), c(1L, 2L, 3L, 4L, -5L, -6L), dtype = "int32")
  expect_jax_equal(jnp_select(list(xs > 10), list(xs), default = -1), c(-1, -1, -1, -1, -1, -1), dtype = "float32")
  expect_jax_equal(jnp_select(list(TRUE, xs > 0), list(5L, xs)), c(5, 5, 5, 5, 5, 5), dtype = "float32")
  expect_error(jnp_select(list(TRUE), list(1, 2)), "condlist must have length equal to choicelist")
  expect_error(jnp_select(list(), list()), "condlist must be non-empty")
  expect_jax_equal(jnp_piecewise(xs, list(xs < 0, xs >= 1), list(function(x) -x, function(x) x^2)), c(2, 0x1.0000000000000p-1, 0, 0, 0x1.2000000000000p+1, 9), dtype = "float32")
  expect_jax_equal(jnp_piecewise(xs, list(xs < 0, xs >= 1), list(function(x) -x, 7, function(x) x * 3)), c(2, 0x1.0000000000000p-1, 0, 0x1.8000000000000p+0, 7, 7), dtype = "float32")
  expect_jax_equal(jnp_piecewise(1:6, list(1:6 > 2, 1:6 > 4), list(function(x, k) x * k, 0.5), k = 10L), c(0L, 0L, 30L, 40L, 0L, 0L), dtype = "int32")
  expect_jax_equal(jnp_piecewise(as_jax(2.5), list(TRUE), list(function(x) x + 1)), 0x1.c000000000000p+1, dtype = "float32")
  expect_jax_equal(jit(function(x) jnp_piecewise(x, list(x > 0), list(jnp_sin, jnp_cos)))(xs), c(-0x1.aa22660000000p-2, 0x1.c152800000000p-1, 1, 0x1.eaee880000000p-2, 0x1.feb7aa0000000p-1, 0x1.2103860000000p-3), dtype = "float32")
  expect_error(jnp_piecewise(xs, list(xs > 0), list(1, 2, 3)), "either 1 or 2 functions are expected; got 3")
  nv <- c(NaN, Inf, -Inf, 1.5, 0)
  expect_jax_equal(jnp_nan_to_num(nv), c(0, 0x1.fffffe0000000p+127, -0x1.fffffe0000000p+127, 0x1.8000000000000p+0, 0), dtype = "float32")
  expect_jax_equal(jnp_nan_to_num(nv, nan = -1, posinf = 100, neginf = -100), c(-1, 100, -100, 0x1.8000000000000p+0, 0), dtype = "float32")
  expect_jax_equal(jnp_nan_to_num(c(1L, 2L)), c(1L, 2L), dtype = "int32")
  expect_jax_equal(jnp_nan_to_num(as_jax(nv, "bfloat16")), c(0, 0x1.fe00000000000p+127, -0x1.fe00000000000p+127, 0x1.8000000000000p+0, 0))
  expect_identical(dtype(jnp_nan_to_num(as_jax(nv, "bfloat16"))), "bfloat16")
  ph <- c(0, 3, 6.5, 9.9, 2, -4.5, -9)
  expect_jax_equal(jnp_unwrap(ph), c(0, 3, 0x1.bc09800000000p-3, -0x1.554ba00000000p+1, -0x1.121fb00000000p+2, -0x1.1ffffa0000000p+2, -0x1.5bc08c0000000p+1), dtype = "float32")
  expect_jax_equal(jnp_unwrap(ph, discont = 4), c(0, 3, 0x1.a000000000000p+2, 0x1.3ccccc0000000p+3, 0x1.090fdc0000000p+3, 0x1.021fb80000000p+3, 0x1.3b2f900000000p+3), dtype = "float32")
  expect_jax_equal(jnp_unwrap(ph, period = 5), c(0, -2, -0x1.c000000000000p+1, -0x1.4666680000000p+2, -3, -0x1.2000000000000p+2, -4), dtype = "float32")
  expect_jax_equal(jnp_unwrap(c(0L, 7L, 15L, 3L, 30L), period = 10L), c(0L, -3L, -5L, -7L, -10L), dtype = "int32")
  expect_jax_equal(jnp_unwrap(c(0L, 7L, 15L, 3L)), c(0, 0x1.6f02600000000p-1, 0x1.3781300000000p+1, 0x1.8000080000000p+1), dtype = "float32")
  expect_jax_equal(jnp_unwrap(matrix(ph[1:6], 2), axis = 0), array(c(0, 3, 0x1.a000000000000p+2, 0x1.cef3c80000000p+1, 2, 0x1.c87ed80000000p+0), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_unwrap(numeric(0)), numeric(0), dtype = "float32")
  expect_error(jnp_unwrap(c(1i, 2)), "does not support complex inputs")
  enable_x64()
  on.exit(enable_x64(FALSE))
  x <- as_jax(xs + 0.125, "float64")
  check_grad_fd(function(v) jnp_sum(jnp_select(list(v < 0, v > 1), list(v^2, jnp_sin(v)), default = v * 3)), x)
  check_grad_fd(function(v) jnp_sum(jnp_piecewise(v, list(v < 0, v >= 1), list(jnp_sin, function(z) z^3, jnp_exp))), x)
  check_grad_fd(function(v) jnp_sum(jnp_unwrap(v * 3)^2), x)
  check_grad_fd(function(v) jnp_sum(jnp_nan_to_num(v)^2), x)
  expect_jax_equal(jnp_unwrap(as_jax(ph, "float64")), c(0, 3, 0x1.bc095777a5d00p-3, -0x1.554ba1ddd812cp+1, -0x1.121fb54442d18p+2, -0x1.2000000000000p+2, -0x1.5bc095777a5d0p+1), dtype = "float64")
  expect_jax_equal(jnp_nan_to_num(c(complex(real = NaN, imaginary = 1), complex(real = 2, imaginary = Inf))), c(complex(real = 0, imaginary = 1), complex(real = 2, imaginary = 0x1.fffffffffffffp+1023)), dtype = "complex128")
  expect_jax_equal(jnp_nan_to_num(as_jax(nv, "float64")), c(0, 0x1.fffffffffffffp+1023, -0x1.fffffffffffffp+1023, 0x1.8000000000000p+0, 0), dtype = "float64")
  pw <- function(v) jnp_piecewise(v, list(v < 0), list(function(z) z^2, function(z) -z))
  mx <- as_jax(matrix(xs, 2), "float64")
  expect_jax_equal(vmap(pw)(mx), a2t_stack_loop(pw, mx))
  uw <- function(v) jnp_unwrap(v * 4)
  expect_jax_equal(vmap(uw, in_axes = 1L)(mx), a2t_stack_loop(uw, mx, 1L))
})

test_that("nanargmax, nanargmin, trim_zeros and trapezoid match JAX", {
  skip_if_no_backend()
  na <- matrix(c(1, NaN, 3, -2, NaN, NaN, NaN, NaN, 0.5, 7, NaN, 7), 3, byrow = TRUE)
  expect_jax_equal(jnp_nanargmax(na), 9L, dtype = "int32")
  expect_jax_equal(jnp_nanargmax(na, axis = 1), c(2L, -1L, 1L), dtype = "int32")
  expect_jax_equal(jnp_nanargmax(na, axis = 0, keepdims = TRUE), array(c(0L, 2L, 0L, 2L), c(1, 4)), dtype = "int32")
  expect_jax_equal(jnp_nanargmax(c(3L, 1L, 4L, 1L)), 2L, dtype = "int32")
  expect_jax_equal(jit(function(x) jnp_nanargmax(x, axis = -1))(na), c(2L, -1L, 1L), dtype = "int32")
  expect_jax_equal(jnp_nanargmin(na), 3L, dtype = "int32")
  expect_jax_equal(jnp_nanargmin(na, axis = 1), c(3L, -1L, 0L), dtype = "int32")
  expect_jax_equal(jnp_nanargmin(na, axis = 0, keepdims = TRUE), array(c(2L, 2L, 0L, 0L), c(1, 4)), dtype = "int32")
  expect_jax_equal(jnp_nanargmin(c(3L, 1L, 4L, 1L)), 1L, dtype = "int32")
  expect_jax_equal(jit(function(x) jnp_nanargmin(x, axis = -1))(na), c(3L, -1L, 0L), dtype = "int32")
  expect_error(jnp_nanargmax(na, out = 1), class = "jax_not_implemented_error")
  tz <- c(0, 0, 1, 0, 2, 0, 0)
  expect_jax_equal(jnp_trim_zeros(tz), c(1, 0, 2), dtype = "float32")
  expect_jax_equal(jnp_trim_zeros(tz, trim = "f"), c(1, 0, 2, 0, 0), dtype = "float32")
  expect_jax_equal(jnp_trim_zeros(tz, trim = "B"), c(0, 0, 1, 0, 2), dtype = "float32")
  expect_jax_equal(jnp_trim_zeros(c(0L, 0L)), integer(0), dtype = "int32")
  t2 <- matrix(c(0L, 0L, 0L, 0L, 0L, 1L, 0L, 0L, 0L, 0L, 2L, 0L, 0L, 0L, 0L, 0L), 4, byrow = TRUE)
  expect_jax_equal(jnp_trim_zeros(t2), array(c(1L, 0L, 0L, 2L), c(2, 2)), dtype = "int32")
  expect_jax_equal(jnp_trim_zeros(t2, axis = 1), array(c(0L, 1L, 0L, 0L, 0L, 0L, 2L, 0L), c(4, 2)), dtype = "int32")
  expect_jax_equal(jnp_trim_zeros(t2, trim = "b", axis = 0), array(c(0L, 0L, 0L, 0L, 1L, 0L, 0L, 0L, 2L, 0L, 0L, 0L), c(3, 4)), dtype = "int32")
  expect_jax_equal(jnp_trim_zeros(t2, trim = "x"), array(c(0L, 0L, 0L, 0L, 0L, 1L, 0L, 0L, 0L, 0L, 2L, 0L, 0L, 0L, 0L, 0L), c(4, 4)), dtype = "int32")
  expect_error(jit(jnp_trim_zeros)(tz), class = "jax_concretization_error")
  y <- c(1, 2.5, 4, 3.5, 0.25)
  expect_jax_equal(jnp_trapezoid(y), 0x1.5400000000000p+3, dtype = "float32")
  expect_jax_equal(jnp_trapezoid(y, dx = 0.5), 0x1.5400000000000p+2, dtype = "float32")
  expect_jax_equal(jnp_trapezoid(y, x = c(0, 1, 3, 3.5, 6)), 0x1.da00000000000p+3, dtype = "float32")
  expect_jax_equal(jnp_trapezoid(1:5), 12, dtype = "float32")
  m <- a2t_m34()
  expect_jax_equal(jnp_trapezoid(m, axis = 0), c(0x1.2000000000000p+2, 0x1.2000000000000p+1, -0x1.8000000000000p-1, 0x1.c000000000000p+0), dtype = "float32")
  expect_jax_equal(jnp_trapezoid(m, x = m * m, axis = 1), c(0x1.1360000000000p+4, -0x1.26e0000000000p+5, -0x1.ad60000000000p+4), dtype = "float32")
  expect_jax_equal(jnp_trapezoid(m, dx = c(1, 2, 0.5)), c(-1, 0x1.c000000000000p+0, 0x1.f000000000000p+2), dtype = "float32")
  expect_jax_equal(jnp_trapezoid(m, dx = matrix(c(1, 2, 3), 3, 1), axis = 1), c(0x1.4000000000000p-1, 0x1.2000000000000p+2, 0x1.8c00000000000p+3), dtype = "float32")
  enable_x64()
  on.exit(enable_x64(FALSE))
  m <- a2t_m34("float64")
  check_grad_fd(function(v) jnp_sum(jnp_trapezoid(v, x = jnp_arange(4) * 0.5 + v[0, ]^2)), m)
  check_grad_fd(function(v) jnp_trapezoid(v[0, ], dx = v[1, 0]), m)
  expect_jax_equal(jnp_trapezoid(m, x = m * m, axis = 1), c(0x1.1360000000000p+4, -0x1.26e0000000000p+5, -0x1.ad60000000000p+4), dtype = "float64")
  expect_jax_equal(jnp_nanargmax(as_jax(na, "float64"), axis = 1), c(2L, -1L, 1L), dtype = "int64")
  tr <- function(v) jnp_trapezoid(v, x = jnp_cumsum(jnp_abs(v)))
  expect_jax_equal(vmap(tr)(m), a2t_stack_loop(tr, m))
})

