test_that("pad differentiates and batches", {
  skip_if_no_backend()
  enable_x64()
  on.exit(enable_x64(FALSE))
  m <- a2t_m34("float64")
  for (mode in c("constant", "wrap", "edge", "reflect", "symmetric", "linear_ramp", "maximum", "mean")) {
    check_grad_fd(function(x) jnp_sum(jnp_sin(jnp_pad(x, list(c(2, 1), c(1, 3)), mode = mode)) * jnp_reshape(jnp_arange(48), c(6L, 8L))), m)
  }
  check_grad_fd(function(x) jnp_sum(jnp_pad(x, 2, mode = "reflect", reflect_type = "odd")^2), m)
  expect_jax_equal(jnp_pad(m, 2, mode = "symmetric", reflect_type = "odd"), array(c(0x1.c000000000000p+0, 0x1.2000000000000p+2, 0x1.2000000000000p+2, 0x1.d000000000000p+2, -0x1.6000000000000p+2, -0x1.6000000000000p+2, -0x1.2400000000000p+4, -0x1.8000000000000p+0, 0x1.4000000000000p+0, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -0x1.0000000000000p-2, -0x1.2000000000000p+2, -0x1.8000000000000p+0, 0x1.4000000000000p+0, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -0x1.0000000000000p-2, -0x1.2000000000000p+2, -0x1.3000000000000p+2, -2, -2, 0x1.8000000000000p-1, 5, 5, 0x1.2800000000000p+3, 0x1.4000000000000p+1, 0x1.0000000000000p-1, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 1, 0x1.c000000000000p+1, 4, 3, 3, 2, -0x1.c000000000000p+1, -0x1.c000000000000p+1, -9, 4, 3, 3, 2, -0x1.c000000000000p+1, -0x1.c000000000000p+1, -9, 0x1.6000000000000p+2, 0x1.6000000000000p+2, 0x1.6000000000000p+2, 0x1.6000000000000p+2, -8, -8, -0x1.5800000000000p+4), c(7, 8)), dtype = "float64")
  expect_jax_equal(jnp_pad(m, c(1, 2), mode = "mean"), array(c(0x1.b555555555555p-1, 0x1.6000000000000p-1, 0x1.5000000000000p+0, 0x1.2000000000000p-1, 0x1.b555555555555p-1, 0x1.b555555555555p-1, 0x1.aaaaaaaaaaaaap+0, 0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, 0x1.aaaaaaaaaaaaap+0, 0x1.aaaaaaaaaaaaap+0, 0x1.4000000000000p+0, -2, 0x1.8000000000000p-1, 5, 0x1.4000000000000p+0, 0x1.4000000000000p+0, 0, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 0, 0, 0x1.0000000000000p-1, 3, 2, -0x1.c000000000000p+1, 0x1.0000000000000p-1, 0x1.0000000000000p-1, 0x1.b555555555555p-1, 0x1.6000000000000p-1, 0x1.5000000000000p+0, 0x1.2000000000000p-1, 0x1.b555555555555p-1, 0x1.b555555555555p-1, 0x1.b555555555555p-1, 0x1.6000000000000p-1, 0x1.5000000000000p+0, 0x1.2000000000000p-1, 0x1.b555555555555p-1, 0x1.b555555555555p-1), c(6, 7)), dtype = "float64")
  check_grad_fd(function(x) jnp_sum(grad(function(z) jnp_sum(jnp_sin(jnp_pad(z, 2, mode = "reflect"))))(x) * m), m)
  check_grad_fd(function(x) jnp_sum(grad(function(z) jnp_sum(jnp_cos(jnp_repeat(z, c(2, 0, 1), axis = 0))))(x) * m), m)
  pf <- function(x) jnp_pad(x, c(2, 3), mode = "reflect")
  expect_jax_equal(vmap(pf)(m), a2t_stack_loop(pf, m))
  pc <- function(x, c) jnp_pad(x, 1, constant_values = c)
  expect_jax_equal(vmap(pc)(m, c(1, 2, 3)), jnp_stack(list(pc(m[0, ], 1), pc(m[1, ], 2), pc(m[2, ], 3))))
})

test_that("packbits and unpackbits match JAX", {
  skip_if_no_backend()
  b <- matrix(c(1L, 0L, 1L, 1L, 0L, 0L, 0L, 1L, 1L, 1L, 0L, 1L, 1L, 0L, 1L, 0L, 1L, 0L, 0L, 1L), 2, byrow = TRUE)
  expect_jax_equal(jnp_packbits(b), c(177L, 218L, 144L), dtype = "uint8")
  expect_jax_equal(jnp_packbits(b, axis = 1), array(c(177L, 106L, 192L, 64L), c(2, 2)), dtype = "uint8")
  expect_jax_equal(jnp_packbits(b, axis = 0, bitorder = "little"), array(c(1L, 2L, 3L, 1L, 2L, 0L, 2L, 1L, 1L, 3L), c(1, 10)), dtype = "uint8")
  expect_jax_equal(jnp_packbits(b > 0, axis = -1, bitorder = "little"), array(c(141L, 86L, 3L, 2L), c(2, 2)), dtype = "uint8")
  u <- as_jax(matrix(c(177, 3, 255, 64), 2, byrow = TRUE), "uint8")
  expect_jax_equal(jnp_unpackbits(u), c(1L, 0L, 1L, 1L, 0L, 0L, 0L, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 0L, 1L, 0L, 0L, 0L, 0L, 0L, 0L), dtype = "uint8")
  expect_jax_equal(jnp_unpackbits(u, axis = 1), array(c(1L, 1L, 0L, 1L, 1L, 1L, 1L, 1L, 0L, 1L, 0L, 1L, 0L, 1L, 1L, 1L, 0L, 0L, 0L, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 1L, 0L, 1L, 0L), c(2, 16)), dtype = "uint8")
  expect_jax_equal(jnp_unpackbits(u, axis = 0, bitorder = "little"), array(c(1L, 0L, 0L, 0L, 1L, 1L, 0L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 1L, 0L), c(16, 2)), dtype = "uint8")
  expect_jax_equal(jnp_unpackbits(u, axis = 1, count = 5), array(c(1L, 1L, 0L, 1L, 1L, 1L, 1L, 1L, 0L, 1L), c(2, 5)), dtype = "uint8")
  expect_jax_equal(jnp_unpackbits(u, count = 40), c(1L, 0L, 1L, 1L, 0L, 0L, 0L, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 1L, 0L, 1L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L, 0L), dtype = "uint8")
  expect_jax_equal(jnp_unpackbits(u, axis = 1, count = -3), array(c(1L, 1L, 0L, 1L, 1L, 1L, 1L, 1L, 0L, 1L, 0L, 1L, 0L, 1L, 1L, 1L, 0L, 0L, 0L, 1L, 0L, 0L, 0L, 0L, 0L, 0L), c(2, 13)), dtype = "uint8")
  expect_jax_equal(jit(function(x) jnp_unpackbits(jnp_packbits(x, axis = 1), axis = 1, count = 10))(b), array(c(1L, 0L, 0L, 1L, 1L, 1L, 1L, 0L, 0L, 1L, 0L, 0L, 0L, 1L, 1L, 0L, 1L, 0L, 1L, 1L), c(2, 10)), dtype = "uint8")
  expect_error(jnp_packbits(c(0.5, 1)), "Expected an input array of integer or boolean data type")
  expect_error(jnp_unpackbits(c(1L, 2L)), "Expected an input array of unsigned byte data type")
  expect_error(jnp_packbits(b, bitorder = "middle"), "'order' must be either 'little' or 'big'")
})

test_that("window functions match JAX", {
  skip_if_no_backend()
  expect_jax_equal(jnp_bartlett(1), c(1), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_bartlett(2), c(0, 0), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_bartlett(7), c(0, 0x1.5555540000000p-2, 0x1.5555540000000p-1, 1, 0x1.5555540000000p-1, 0x1.5555540000000p-2, 0), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_blackman(1), c(1), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_blackman(2), c(-0x1.0000000000000p-26, -0x1.0000000000000p-26), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_blackman(7), c(-0x1.0000000000000p-26, 0x1.0a3d700000000p-3, 0x1.428f5c0000000p-1, 0x1.fffffe0000000p-1, 0x1.428f5a0000000p-1, 0x1.0a3d5e0000000p-3, -0x1.0000000000000p-26), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_hamming(1), c(1), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_hamming(2), c(0x1.47ae180000000p-4, 0x1.47ae180000000p-4), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_hamming(7), c(0x1.47ae180000000p-4, 0x1.3d70a60000000p-2, 0x1.8a3d720000000p-1, 1, 0x1.8a3d700000000p-1, 0x1.3d709a0000000p-2, 0x1.47ae180000000p-4), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_hanning(1), c(1), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_hanning(2), c(0, 0), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_hanning(7), c(0, 0x1.0000000000000p-2, 0x1.8000000000000p-1, 1, 0x1.7ffffe0000000p-1, 0x1.ffffe80000000p-3, 0), dtype = "float32", tolerance = 1e-7)
  expect_jax_equal(jnp_hanning(0), numeric(0), dtype = "float32")
  expect_error(jit(jnp_hamming)(5L), class = "jax_concretization_error")
  enable_x64()
  on.exit(enable_x64(FALSE))
  expect_jax_equal(jnp_bartlett(6), c(0, 0x1.9999999999998p-2, 0x1.999999999999ap-1, 0x1.999999999999ap-1, 0x1.9999999999998p-2, 0), dtype = "float64")
  expect_jax_equal(jnp_blackman(6), c(-0x1.0000000000000p-56, 0x1.9b2d607a9b3eap-3, 0x1.b2ce417af2c9ep-1, 0x1.b2ce417af2c9ep-1, 0x1.9b2d607a9b3eep-3, -0x1.0000000000000p-56), dtype = "float64")
  expect_jax_equal(jnp_hamming(6), c(0x1.47ae147ae147cp-4, 0x1.976690036c2c2p-2, 0x1.d30509e9cf08ap-1, 0x1.d30509e9cf08bp-1, 0x1.976690036c2c4p-2, 0x1.47ae147ae147cp-4), dtype = "float64")
  expect_jax_equal(jnp_hanning(6), c(0, 0x1.61c8864680b58p-2, 0x1.cf1bbcdcbfa54p-1, 0x1.cf1bbcdcbfa54p-1, 0x1.61c8864680b5ap-2, 0), dtype = "float64")
  enable_x64(FALSE)
  skip_if_not(exists("jnp_i0", mode = "function"))
  expect_jax_equal(jnp_kaiser(1, 3), c(1), dtype = "float32")
  expect_jax_equal(jnp_kaiser(6, 3), c(0x1.a39aa20000000p-3, 0x1.3fdebc0000000p-1, 0x1.e789980000000p-1, 0x1.e789980000000p-1, 0x1.3fdebc0000000p-1, 0x1.a39aa20000000p-3), dtype = "float32", tolerance = 1e-6)
  expect_jax_equal(jnp_kaiser(5, 0.5), c(0x1.e16fd20000000p-1, 0x1.f8451a0000000p-1, 1, 0x1.f8451a0000000p-1, 0x1.e16fd20000000p-1), dtype = "float32", tolerance = 1e-6)
  enable_x64()
  expect_jax_equal(jnp_kaiser(7, 2.5), c(0x1.3742ec59b5b35p-2, 0x1.4307f7deaf209p-1, 0x1.cb7bd109c5fe4p-1, 1, 0x1.cb7bd109c5fe4p-1, 0x1.4307f7deaf209p-1, 0x1.3742ec59b5b35p-2), dtype = "float64")
  check_grad_fd(function(b) jnp_sum(jnp_kaiser(6, b)), as_jax(2.5, "float64"))
})

test_that("vectorize matches JAX", {
  skip_if_no_backend()
  m <- a2t_m34()
  x <- a2t_x24()
  expect_jax_equal(jnp_vectorize(function(a, b) a * 2 + b)(m, c(1, 2, 3, 4)), array(c(0x1.c000000000000p+1, 9, 0x1.0000000000000p-1, -2, 0x1.c000000000000p+1, 12, 4, 0, 5, 10, 8, -3), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_vectorize(jnp_matmul, signature = "(n,m),(m)->(n)")(x, c(1, -1, 2, 0.5)), array(c(-0x1.5000000000000p+2, 0x1.3800000000000p+3, -0x1.0000000000000p-2, 0x1.d800000000000p+3, 0x1.3000000000000p+2, 0x1.3c00000000000p+4), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_vectorize(function(a) jnp_sum(a), signature = "(n)->()")(x), array(c(-9, 15, -1, 23, 7, 31), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_vectorize(function(a, b) jnp_dot(a, b), signature = "(n),(n)->()")(m, jnp_ones(c(2L, 1L, 4L))), array(c(0x1.6000000000000p+1, 0x1.6000000000000p+1, 0x1.5000000000000p+2, 0x1.5000000000000p+2, 0x1.2000000000000p+1, 0x1.2000000000000p+1), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_vectorize(function(a, p) a^p, excluded = 1L)(m, 2L), array(c(0x1.9000000000000p+0, 16, 0x1.0000000000000p-4, 4, 0x1.2000000000000p-1, 25, 0x1.0000000000000p-2, 0x1.2000000000000p+1, 1, 9, 4, 0x1.8800000000000p+3), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_vectorize(function(a, p = 1) a * p, excluded = "p")(m, p = 3), array(c(0x1.e000000000000p+1, 12, -0x1.8000000000000p-1, -6, 0x1.2000000000000p+1, 15, 0x1.8000000000000p+0, -0x1.2000000000000p+2, 3, 9, 6, -0x1.5000000000000p+3), c(3, 4)), dtype = "float32")
  expect_jax_equal(jnp_vectorize(function(a, p = 1) a * p)(m, p = 3), array(c(0x1.4000000000000p+0, 4, -0x1.0000000000000p-2, -2, 0x1.8000000000000p-1, 5, 0x1.0000000000000p-1, -0x1.8000000000000p+0, 1, 3, 2, -0x1.c000000000000p+1), c(3, 4)), dtype = "float32")
  a2t_expect_list(jnp_vectorize(function(a) list(jnp_min(a), jnp_max(a)), signature = "(n)->(),()")(m), list(c(-2, -0x1.8000000000000p+0, -0x1.c000000000000p+1), c(3, 4, 5)), dtype = "float32")
  expect_jax_equal(jnp_vectorize(function(a, b) a - b)(matrix(c(1, 2), 2, 1), c(10, 20, 30)), array(c(-9, -8, -19, -18, -29, -28), c(2, 3)), dtype = "float32")
  expect_jax_equal(jit(function(a, b) jnp_vectorize(jnp_matmul, signature = "(n,m),(m,k)->(n,k)")(a, jnp_transpose(b)))(x, m), array(c(-0x1.1000000000000p+2, 0x1.8800000000000p+3, 0x1.4000000000000p+0, 0x1.1c00000000000p+4, 0x1.b000000000000p+2, 0x1.7400000000000p+4, -0x1.bc00000000000p+3, 0x1.1a00000000000p+4, -0x1.b000000000000p+1, 0x1.c200000000000p+4, 0x1.c800000000000p+2, 0x1.3500000000000p+5, -0x1.1000000000000p+3, 5, -4, 0x1.3000000000000p+3, 0x1.0000000000000p-1, 14), c(2, 3, 3)), dtype = "float32")
  expect_error(jnp_vectorize(jnp_sum, signature = "(n)->(")(m), "not a valid gufunc signature")
  expect_error(jnp_vectorize(jnp_matmul, signature = "(n,m),(m)->(n)")(m, c(1, 2)), "inconsistent size for core dimension 'm'")
  expect_error(jnp_vectorize(jnp_matmul, signature = "(n,m),(m)->(n)")(c(1, 2), c(1, 2)), "does not have enough dimensions")
  expect_error(jnp_vectorize(function(a) a, signature = "(n)->()")(m), "output shape \\(4,\\) does not match core dimensions")
  expect_error(jnp_vectorize(function(a) a, signature = "(n)->(),()")(m), "output must be a tuple")
  expect_error(jnp_vectorize(function(a, b) a, signature = "(n),(n)->()")(m), "wrong number of positional arguments")
  expect_error(jnp_vectorize(jnp_sum, excluded = -1L), "contains negative numbers")
  expect_error(jnp_vectorize(jnp_sum, excluded = list(TRUE)), "can only exclude integer or string arguments")
  expect_error(with_jax_config("jax_numpy_rank_promotion", "raise", jnp_vectorize(jnp_add)(m, c(1, 2, 3, 4))), "require rank promotion")
  enable_x64()
  on.exit(enable_x64(FALSE))
  m64 <- as_jax(m, "float64")
  check_grad_fd(function(v) jnp_sum(jnp_vectorize(function(a, b) jnp_dot(jnp_sin(a), b), signature = "(n),(n)->()")(v, v[0, ])), m64)
})

test_that("mgrid, ogrid, r_, c_, result_type and promote_types match JAX", {
  skip_if_no_backend()
  expect_jax_equal(jnp_mgrid(sl(0, 5)), c(0L, 1L, 2L, 3L, 4L), dtype = "int32")
  expect_jax_equal(jnp_mgrid(sl(1, 3), sl(0, 4, 2)), array(c(1L, 0L, 2L, 0L, 1L, 2L, 2L, 2L), c(2, 2, 2)), dtype = "int32")
  expect_jax_equal(jnp_mgrid(sl(0, 1, 3i), sl(0, 2)), array(c(0, 0, 0x1.0000000000000p-1, 0, 1, 0, 0, 1, 0x1.0000000000000p-1, 1, 1, 1), c(2, 3, 2)), dtype = "float32")
  expect_jax_equal(jnp_mgrid(sl(-1, 1, 5i)), c(-1, -0x1.0000000000000p-1, 0, 0x1.0000000000000p-1, 1), dtype = "float32")
  expect_jax_equal(jnp_mgrid(list(sl(0, 3))), array(c(0L, 1L, 2L), c(1, 3)), dtype = "int32")
  expect_jax_equal(jnp_mgrid(sl(0, 2, 0.5), sl(stop = 2)), array(c(0, 0, 0x1.0000000000000p-1, 0, 1, 0, 0x1.8000000000000p+0, 0, 0, 1, 0x1.0000000000000p-1, 1, 1, 1, 0x1.8000000000000p+0, 1), c(2, 4, 2)), dtype = "float32")
  a2t_expect_list(jnp_ogrid(sl(0, 3), sl(1, 3)), list(array(c(0L, 1L, 2L), c(3, 1)), array(c(1L, 2L), c(1, 2))), dtype = "int32")
  expect_jax_equal(jnp_ogrid(sl(2, 4)), c(2L, 3L), dtype = "int32")
  a2t_expect_list(jnp_ogrid(sl(0, 1, 3i), sl(0, 2)), list(array(c(0, 0x1.0000000000000p-1, 1), c(3, 1)), array(c(0, 1), c(1, 2))), dtype = "float32")
  expect_jax_equal(jnp_r_(c(1L, 2L), 0L, sl(3, 6)), c(1L, 2L, 0L, 3L, 4L, 5L), dtype = "int32")
  expect_jax_equal(jnp_r_(sl(-1, 1, 5i), c(4, 5)), c(-1, -0x1.0000000000000p-1, 0, 0x1.0000000000000p-1, 1, 4, 5), dtype = "float32")
  expect_jax_equal(jnp_r_("0,2", c(1, 2, 3), c(4, 5, 6)), array(c(1, 4, 2, 5, 3, 6), c(2, 3)), dtype = "float32")
  expect_jax_equal(jnp_r_("0,2,0", c(1, 2, 3), c(4, 5, 6)), array(c(1, 2, 3, 4, 5, 6), c(6, 1)), dtype = "float32")
  expect_jax_equal(jnp_r_("1,2,0", c(1, 2, 3), c(4, 5, 6)), array(c(1, 2, 3, 4, 5, 6), c(3, 2)), dtype = "float32")
  expect_jax_equal(jnp_r_("-1,3,1", matrix(1:4, 2)), array(c(1L, 2L, 3L, 4L), c(2, 2, 1)), dtype = "int32")
  expect_jax_equal(jnp_r_("r", c(1, 2), c(3, 4)), array(c(1, 2, 3, 4), c(1, 4)), dtype = "float32")
  expect_jax_equal(jnp_r_("c", c(1, 2), c(3, 4)), array(c(1, 2, 3, 4), c(4, 1)), dtype = "float32")
  expect_jax_equal(jnp_c_(c(1, 2), c(3, 4)), array(c(1, 2, 3, 4), c(2, 2)), dtype = "float32")
  expect_jax_equal(jnp_c_(matrix(1:4, 2), c(5L, 6L)), array(c(1L, 2L, 3L, 4L, 5L, 6L), c(2, 3)), dtype = "int32")
  expect_jax_equal(jnp_c_(sl(0, 3), c(7, 8, 9)), array(c(0, 1, 2, 7, 8, 9), c(3, 2)), dtype = "float32")
  expect_error(jnp_r_("a,b", c(1, 2)), "could not understand directive")
  expect_error(jnp_r_(c(1, 2), "r"), "string directive must be placed at the beginning")
  expect_identical(jnp_result_type(1L, as_jax(1, "float32")), "float32")
  expect_identical(jnp_result_type(as_jax(1L, "int8"), as_jax(1L, "uint8")), "int16")
  expect_identical(jnp_result_type("int32", 2.5), "float32")
  expect_identical(jnp_promote_types("int8", "float16"), "float16")
  expect_identical(jnp_promote_types("bool", "int16"), "int16")
})

test_that("weak types follow JAX", {
  skip_if_no_backend()
  expect_identical(jaxR:::aval_of(jnp_tile(2.5, 3))$weak, TRUE)
  expect_identical(dtype(jnp_tile(2.5, 3)), "float32")
  expect_identical(jaxR:::aval_of(jnp_repeat(2.5, 3))$weak, TRUE)
  expect_identical(dtype(jnp_repeat(2.5, 3)), "float32")
  expect_identical(jaxR:::aval_of(jnp_roll(2.5, 1))$weak, TRUE)
  expect_identical(dtype(jnp_roll(2.5, 1)), "float32")
  expect_identical(jaxR:::aval_of(jnp_select(list(TRUE), list(2.5)))$weak, TRUE)
  expect_identical(dtype(jnp_select(list(TRUE), list(2.5))), "float32")
  expect_identical(jaxR:::aval_of(jnp_nan_to_num(2.5))$weak, FALSE)
  expect_identical(dtype(jnp_nan_to_num(2.5)), "float32")
  expect_identical(jaxR:::aval_of(jnp_pad(2.5, 1))$weak, TRUE)
  expect_identical(dtype(jnp_pad(2.5, 1)), "float32")
  expect_identical(jaxR:::aval_of(jnp_unwrap(c(0L, 7L, 15L)))$weak, FALSE)
  expect_identical(dtype(jnp_unwrap(c(0L, 7L, 15L))), "float32")
  expect_identical(jaxR:::aval_of(jnp_resize(2.5, 2))$weak, TRUE)
  expect_identical(dtype(jnp_resize(2.5, 2)), "float32")
  expect_identical(jaxR:::aval_of(jnp_nonzero(c(1, 2, 3))[[1L]])$weak, FALSE)
  expect_identical(dtype(jnp_nonzero(c(1, 2, 3))[[1L]]), "int32")
  expect_identical(jaxR:::aval_of(jnp_unravel_index(5, c(2, 3))[[1L]])$weak, TRUE)
  expect_identical(dtype(jnp_unravel_index(5, c(2, 3))[[1L]]), "int32")
  expect_identical(jaxR:::aval_of(jnp_r_(1, 2))$weak, TRUE)
  expect_identical(dtype(jnp_r_(1, 2)), "float32")
  expect_identical(jaxR:::aval_of(jnp_vstack(list(1, 2)))$weak, TRUE)
  expect_identical(dtype(jnp_vstack(list(1, 2))), "float32")
  expect_identical(jaxR:::aval_of(jnp_piecewise(2.5, list(TRUE), list(function(x) x * 2)))$weak, FALSE)
  expect_identical(dtype(jnp_piecewise(2.5, list(TRUE), list(function(x) x * 2))), "float32")
  expect_identical(jaxR:::aval_of(jnp_vectorize(function(a, b) a + b)(2.5, 1))$weak, TRUE)
  expect_identical(dtype(jnp_vectorize(function(a, b) a + b)(2.5, 1)), "float32")
  expect_identical(jaxR:::aval_of(jnp_hanning(3))$weak, FALSE)
  expect_identical(dtype(jnp_hanning(3)), "float32")
  expect_identical(jaxR:::aval_of(jnp_trace(jnp_eye(2)))$weak, FALSE)
  expect_identical(dtype(jnp_trace(jnp_eye(2))), "float32")
})

test_that("functions give the same values under jit", {
  skip_if_no_backend()
  same <- function(a, b) {
    if (is.list(b) && !inherits(b, "jax_value")) {
      expect_length(a, length(b))
      for (i in seq_along(b)) expect_jax_equal(a[[i]], as.array(b[[i]]), dtype = dtype(b[[i]]))
    } else expect_jax_equal(a, as.array(b), dtype = dtype(b))
  }
  m <- a2t_m34()
  fs <- list(
    function(a) jnp_tile(a, c(2, 1)), function(a) jnp_resize(a, c(5, 2)), function(a) jnp_rot90(a, 3),
    function(a) jnp_permute_dims(a, c(1, 0)), function(a) jnp_rollaxis(a, 1), function(a) jnp_meshgrid(a[0, ], a[1, ]),
    function(a) jnp_vstack(list(a, a[0, ])), function(a) jnp_unstack(a, axis = 1),
    function(a) jnp_select(list(a > 0, a < -1), list(a, a * 2), default = 3), function(a) jnp_nan_to_num(a / 0),
    function(a) jnp_unwrap(a * 3), function(a) jnp_trapezoid(a, dx = 0.5), function(a) jnp_vander(a[0, ]),
    function(a) jnp_tensordot(a, jnp_transpose(a), 1), function(a) jnp_matvec(a, a[0, ]), function(a) jnp_vecmat(a[, 0], a),
    function(a) jnp_vecdot(a, a), function(a) jnp_tril(a), function(a) jnp_triu(a, 1), function(a) jnp_trace(a, 1),
    function(a) jnp_pad(a, 1, mode = "edge"), function(a) jnp_pad(a, c(2, 1), mode = "linear_ramp"),
    function(a) jnp_einsum("ij,kj->ik", a, a), function(a) jnp_packbits(a > 0, axis = 1),
    function(a) jnp_roll(a, 2), function(a) jnp_repeat(a, 2, axis = 1), function(a) jnp_split(a, 2, axis = 1),
    function(a) jnp_nanargmax(a, axis = 0), function(a) jnp_piecewise(a, list(a > 0), list(function(z) z * 2, -1)),
    function(a) jnp_vectorize(function(u, v) jnp_dot(u, v), signature = "(n),(n)->()")(a, a[0, ]),
    function(a) jnp_nonzero(a > 0, size = 5), function(a) jnp_put(a, c(1, 13), c(9, 8), inplace = FALSE),
    function(a) jnp_place(a, a > 1, c(-1, -2), inplace = FALSE))
  for (f in fs) same(jit(f)(m), f(m))
})

test_that("jnp_where with one argument is nonzero", {
  skip_if_no_backend()
  skip_if_not("size" %in% names(formals(jnp_where)))
  a <- as_jax(matrix(c(0, 1.5, -2, 0, 3, 0), 2, byrow = TRUE))
  a2t_expect_list(jnp_where(a), list(c(0L, 0L, 1L), c(1L, 2L, 1L)), dtype = "int32")
  a2t_expect_list(jnp_where(a, size = 4, fill_value = -1), list(c(0L, 0L, 1L, -1L), c(1L, 2L, 1L, -1L)), dtype = "int32")
  a2t_expect_list(jit(function(x) jnp_where(x > 0, size = 2))(a), list(c(0L, 1L), c(1L, 1L)), dtype = "int32")
  expect_error(jnp_where(a, 1, 2, size = 2), "size and fill_value arguments cannot be used in three-term where function")
  expect_error(jnp_where(a, 1), "Either both or neither of the x and y arguments should be provided")
})
